import React, { useEffect, useMemo, useState } from 'react';
import { Link, NavLink, Navigate, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom';
import mermaid from 'mermaid';
import { api, getToken, setToken } from './api';
import LiteratureReview from './LiteratureReview';

const statuses = { embedded: 'Ready', embedding: 'AI processing — please wait', processed: 'Processed', processing: 'AI processing — please wait', ready: 'Ready to process', failed: 'Failed', created: 'Created', validating: 'Validating' };
const artifactLabels = { report: 'Project Report', 'ieee-report': 'IEEE Report', 'database-diagram': 'Database Diagram', 'architecture-diagram': 'Architecture Diagram' };
const projectCache = new Map();
let projectListCache = [];
const cacheProject = project => { if (project?.id) projectCache.set(String(project.id), project); return project; };
const cacheProjects = projects => { projectListCache = (projects || []).map(cacheProject); return projectListCache; };
function useProject(id) {
  const key = id ? String(id) : '';
  const [project, setProject] = useState(() => projectCache.get(key) || null);
  const [error, setError] = useState('');
  useEffect(() => {
    if (!key) { setProject(null); setError(''); return undefined; }
    let live = true;
    setProject(projectCache.get(key) || null);
    setError('');
    const load = () => api.project(key).then(result => { cacheProject(result); if (live) setProject(result); }).catch(err => { if (live && !projectCache.has(key)) setError(err.message); });
    load();
    const timer = setInterval(load, 3000);
    return () => { live = false; clearInterval(timer); };
  }, [key]);
  return { project, error };
}
function App() {
  const [theme, setTheme] = useState(() => localStorage.getItem('archstudio_theme') || 'batman');
  const [user, setUser] = useState(null);
  const [authReady, setAuthReady] = useState(false);
  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem('archstudio_theme', theme); }, [theme]);
  useEffect(() => { const token = getToken(); if (token) api.me().then(setUser).catch(() => setUser(null)).finally(() => setAuthReady(true)); else setAuthReady(true); const expire = () => setUser(null); window.addEventListener('auth-expired', expire); return () => window.removeEventListener('auth-expired', expire); }, []);
  const logout = () => { setToken(null); setUser(null); };
  if (!authReady) return <div className="auth-layout"><div className="auth-panel"><LoadingCard /></div></div>;
  return <Routes>
    <Route path="/login" element={user ? <Navigate to="/" /> : <AuthPageV3 mode="login" onAuth={setUser} />} />
    <Route path="/register" element={user ? <Navigate to="/" /> : <AuthPageV3 mode="register" onAuth={setUser} />} />
    <Route path="/auth/callback" element={<AuthCallback onAuth={setUser} />} />
    <Route path="/auth/confirm" element={<AuthConfirmation onAuth={setUser} />} />
    <Route path="/forgot-password" element={<ForgotPassword />} />
    <Route path="/auth/reset-password" element={<ResetPassword />} />
    <Route path="*" element={user ? <SessionRouter user={user} logout={logout} theme={theme} setTheme={setTheme} /> : <Navigate to="/login" replace />} />
  </Routes>;
}

function SessionRouter(props) { const location = useLocation(); if (location.pathname === '/literature-review' || location.pathname.endsWith('/literature-review') || location.pathname.endsWith('/research')) { const projectId = location.pathname.split('/')[2] || ''; return <div className="app-shell"><main className="main"><div className="content"><div className="feature-navigation"><Link className="dashboard-nav" to="/">← Dashboard</Link>{projectId && <Link className="workspace-nav" to={`/projects/${projectId}`}>Workspace</Link>}</div><LiteratureReview projectId={projectId} /></div></main></div>; } if (location.pathname === '/paper') return <div className="app-shell"><main className="main"><div className="content"><ArtifactLibrary kind="reports" /></div></main></div>; return <Shell {...props} />; }
function Shell({ user, logout, theme, setTheme }) {
  const location = useLocation();
  const inProject = location.pathname.startsWith('/projects/') && location.pathname !== '/projects/';
  const projectId = inProject ? location.pathname.split('/')[2] : '';
  const { project: projectContext } = useProject(projectId);
  return <div className="app-shell"><main className="main"><header className="topbar"><Link className="header-brand" to="/"><span className="brand-mark">A</span><span>ArchStudio<span className="accent">AI</span></span></Link><div className="header-context">{inProject ? <><span>Project Workspace</span><b>/</b><strong>{projectContext?.name || 'Loading project…'}</strong></> : <><span>Engineering intelligence</span><b>·</b><Link to="/">Dashboard</Link></>}</div><div className="topbar-right"><span className="status-dot">●</span><span className="workspace-label">Local AI workspace</span><button className="header-control" onClick={() => setTheme(theme === 'batman' ? 'superman' : 'batman')} title="Switch theme">{theme === 'batman' ? '☾' : '☀'}<span className="control-label">{theme === 'batman' ? 'Batman dark' : 'Superman light'}</span></button><span className="topbar-divider" /><details className="profile-menu"><summary><span className="avatar small">{(user.email || 'A')[0].toUpperCase()}</span><span className="profile-name">{user.user_metadata?.name || user.email?.split('@')[0]}</span><span>⌄</span></summary><div className="profile-dropdown"><span className="muted">{user.email}</span><Link to="/">Dashboard</Link><button onClick={logout}>Log out</button></div></details></div></header><div className="content"><Routes><Route path="/" element={<Dashboard />} /><Route path="/projects" element={<Navigate to="/" replace />} /><Route path="/projects/:id" element={<Workspace />} /><Route path="/projects/:id/reports" element={<ArtifactLibrary kind="reports" />} /><Route path="/projects/:id/diagrams" element={<ArtifactLibrary kind="diagrams" />} /><Route path="/projects/:id/research" element={<ArtifactLibrary kind="research" />} /><Route path="/projects/:id/chat" element={<GlobalChat />} /><Route path="/reports" element={<ArtifactLibrary kind="reports" />} /><Route path="/diagrams" element={<ArtifactLibrary kind="diagrams" />} /><Route path="/research" element={<ArtifactLibrary kind="research" />} /><Route path="/chat" element={<GlobalChat />} /><Route path="*" element={<Navigate to="/" />} /></Routes></div></main></div>;
}
function NavItem({ to, icon, children }) { return <NavLink className={({ isActive }) => isActive ? 'nav-item active' : 'nav-item'} to={to}><span>{icon}</span>{children}</NavLink>; }

function AuthCallback({ onAuth }) {
  const navigate = useNavigate();
  const [error, setError] = useState('');
  useEffect(() => {
    const params = new URLSearchParams(window.location.hash.replace(/^#/, ''));
    const token = params.get('access_token');
    const authError = params.get('error_description') || new URLSearchParams(window.location.search).get('error_description');
    if (authError) { setError('Authentication was cancelled or could not be completed.'); return; }
    if (!token) { setError('Authentication callback was invalid.'); return; }
    setToken(token);
    api.me().then(user => { onAuth(user); navigate('/'); }).catch(() => { setToken(null); setError('Authentication could not be completed. Please try again.'); });
  }, [navigate, onAuth]);
  return <div className="auth-layout"><div className="auth-panel auth-callback"><div className="auth-form"><div className="eyebrow">AUTHENTICATION</div><h2>{error ? 'Sign-in failed' : 'Completing sign-in…'}</h2>{error && <><p className="muted">{error}</p><Link className="primary-button wide" to="/login">Return to sign in</Link></>}</div></div></div>;
}

function AuthConfirmation({ onAuth }) {
  const navigate = useNavigate();
  const [state, setState] = useState('checking');
  useEffect(() => {
    let live = true;
    const confirm = async () => {
      const hash = new URLSearchParams(window.location.hash.replace(/^#/, ''));
      const accessToken = hash.get('access_token');
      const error = hash.get('error_description') || new URLSearchParams(window.location.search).get('error_description');
      if (error) { if (live) setState('failed'); return; }
      if (accessToken) setToken(accessToken);
      try {
        const currentUser = await api.me();
        const verified = Boolean(currentUser.email_confirmed || currentUser.email_confirmed_at || currentUser.confirmed_at || currentUser.email_verified);
        if (!verified) throw new Error('Email verification is not complete.');
        if (live) { onAuth(currentUser); setState('success'); }
      } catch {
        if (live) setState('failed');
      }
    };
    confirm();
    return () => { live = false; };
  }, [onAuth]);
  return <div className="auth-layout confirmation-layout"><div className="confirmation-card"><div className="brand"><span className="brand-mark">A</span><span>ArchStudio<span className="accent">AI</span></span></div>{state === 'checking' && <><div className="confirmation-icon checking">…</div><h1>Confirming your email</h1><p className="muted">We’re securely checking your account status.</p></>}{state === 'success' && <><div className="confirmation-icon">✓</div><div className="eyebrow">EMAIL CONFIRMED</div><h1>Email verified successfully</h1><p className="muted">Your account is ready to use.</p><button className="primary-button wide" onClick={() => navigate('/')}>Enter Workspace →</button></>}{state === 'failed' && <><div className="confirmation-icon failed">!</div><div className="eyebrow">CONFIRMATION INCOMPLETE</div><h1>Email confirmation failed</h1><p className="muted">This link may have expired, already been used, or is invalid. Please request a new confirmation email.</p><Link className="secondary-button wide" to="/login">Return to Sign In</Link></>}</div></div>;
}

function ForgotPassword() {
  const [email, setEmail] = useState(''); const [busy, setBusy] = useState(false); const [sent, setSent] = useState(false); const [error, setError] = useState('');
  const submit = async (e) => { e.preventDefault(); setBusy(true); setError(''); try { await api.forgotPassword({ email }); setSent(true); } catch (err) { setError(err.message || 'Could not send the recovery email.'); } finally { setBusy(false); } };
  return <div className="auth-layout"><div className="auth-panel"><div className="auth-form"><div className="eyebrow">PASSWORD RECOVERY</div><h2>{sent ? 'Check your email' : 'Forgot your password?'}</h2><p className="muted">{sent ? `If an account exists for ${email}, we sent a secure password reset link.` : 'Enter your account email and we’ll send you a secure reset link.'}</p>{sent ? <><div className="notice-box">Check your inbox and spam folder for the reset link.</div><Link className="primary-button wide" to="/login">Return to sign in</Link></> : <form onSubmit={submit}><label>Email<input required type="email" autoComplete="email" value={email} onChange={e => setEmail(e.target.value)} /></label>{error && <div className="error-box">{error}</div>}<button className="primary-button wide" disabled={busy}>{busy ? 'Sending…' : 'Send reset link'}</button><Link className="switch-auth" to="/login">Back to sign in</Link></form>}</div></div></div>;
}

function PasswordField({ label, value, onChange }) { const [visible, setVisible] = useState(false); return <label className="password-field">{label}<span className="password-input-wrap"><input required minLength="8" type={visible ? 'text' : 'password'} autoComplete="new-password" value={value} onChange={onChange} /><button type="button" className="password-toggle" aria-label={visible ? 'Hide password' : 'Show password'} onClick={() => setVisible(!visible)}>{visible ? '◉' : '◌'}</button></span></label>; }

function AuthPageV3({ mode, onAuth }) { const navigate = useNavigate(); const [form, setForm] = useState({ name: '', email: '', password: '', confirm_password: '' }); const [busy, setBusy] = useState(false); const [oauthBusy, setOauthBusy] = useState(''); const [error, setError] = useState(''); const submit = async e => { e.preventDefault(); setBusy(true); setError(''); try { const result = await (mode === 'login' ? api.login({ email: form.email, password: form.password }) : api.register(form)); if (!result.session?.access_token) { setError(`Confirmation email sent to ${form.email}. Open it, then sign in.`); return; } setToken(result.session.access_token); onAuth(result.user); navigate('/'); } catch (err) { setError(err.message || 'Authentication could not be completed.'); } finally { setBusy(false); } }; const oauth = async provider => { setOauthBusy(provider); setError(''); try { const result = await api.oauth(provider); if (!result?.url) throw new Error(); window.location.assign(result.url); } catch { setOauthBusy(''); setError('Could not start social sign-in. Please try again.'); } }; return <div className="auth-layout"><div className="auth-art"><div className="brand"><span className="brand-mark">A</span><span>ArchStudio<span className="accent">AI</span></span></div><div className="auth-quote"><h1><span className="quote-mark">“</span>Give your codebase a second brain.<span className="quote-mark">”</span></h1><p>Understand, visualize and explain your software projects with grounded local AI.</p></div></div><div className="auth-panel"><div className="auth-form"><div className="eyebrow">{mode === 'login' ? 'WELCOME BACK' : 'GET STARTED'}</div><h2>{mode === 'login' ? 'Sign in to your workspace' : 'Create your workspace'}</h2><p className="muted">{mode === 'login' ? 'Your project intelligence is waiting.' : 'Turn any repository into a living knowledge base.'}</p><form onSubmit={submit}>{mode === 'register' && <label>Full name<input required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label>}<label>Email<input required type="email" autoComplete="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></label><PasswordField label="Password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} />{mode === 'register' && <PasswordField label="Confirm password" value={form.confirm_password} onChange={e => setForm({ ...form, confirm_password: e.target.value })} />}<button className="primary-button wide" disabled={busy || !!oauthBusy}>{busy ? 'Please wait…' : mode === 'login' ? 'Sign in' : 'Create account'}</button></form>{mode === 'login' && <Link className="forgot-password" to="/forgot-password">Forgot password?</Link>}<div className="oauth-divider"><span>OR</span></div><div className="oauth-options"><button type="button" className="secondary-button oauth-button" disabled={busy || !!oauthBusy} onClick={() => oauth('google')}><strong>G</strong>{oauthBusy === 'google' ? 'Connecting…' : 'Continue with Google'}</button><button type="button" className="secondary-button oauth-button" disabled={busy || !!oauthBusy} onClick={() => oauth('github')}><strong>◈</strong>{oauthBusy === 'github' ? 'Connecting…' : 'Continue with GitHub'}</button></div>{error && <div className="error-box">{error}</div>}<p className="switch-auth">{mode === 'login' ? 'New to ArchStudioAI?' : 'Already have an account?'} <Link to={mode === 'login' ? '/register' : '/login'}>{mode === 'login' ? 'Create an account' : 'Sign in'}</Link></p></div></div></div>; }

function ResetPassword() {
  const navigate = useNavigate(); const [form, setForm] = useState({ password: '', confirm_password: '' }); const [busy, setBusy] = useState(false); const [state, setState] = useState('ready'); const [error, setError] = useState('');
  useEffect(() => { const params = new URLSearchParams(window.location.hash.replace(/^#/, '')); const token = params.get('access_token'); if (!token) { setState('invalid'); setError(params.get('error_description') || 'This password reset link is invalid or expired.'); } else setToken(token); }, []);
  const submit = async (e) => { e.preventDefault(); setBusy(true); setError(''); try { await api.updatePassword(form); setToken(null); navigate('/register'); } catch (err) { setError(err.message || 'Password could not be updated.'); } finally { setBusy(false); } };
  return <div className="auth-layout centered-auth"><div className="auth-panel"><div className="auth-form"><div className="eyebrow">PASSWORD RECOVERY</div>{state === 'success' ? <><h2>Password changed</h2><p className="muted">Your password has been updated successfully.</p><button className="primary-button wide" onClick={() => navigate('/register')}>Continue to registration</button></> : state === 'invalid' ? <><h2>Reset link unavailable</h2><p className="muted">{error}</p><Link className="primary-button wide" to="/login">Return to sign in</Link></> : <><h2>Choose a new password</h2><p className="muted">Use at least 8 characters. After changing it, you’ll return to registration.</p><form onSubmit={submit}><PasswordField label="New password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} /><PasswordField label="Confirm new password" value={form.confirm_password} onChange={e => setForm({ ...form, confirm_password: e.target.value })} />{error && <div className="error-box">{error}</div>}<button className="primary-button wide" disabled={busy}>{busy ? 'Updating…' : 'Change password'}</button></form></>}</div></div></div>;
}

function AuthPageV2({ mode, onAuth }) {
  const navigate = useNavigate();
  const [form, setForm] = useState({ name: '', email: '', password: '', confirm_password: '' });
  const [busy, setBusy] = useState(false);
  const [oauthBusy, setOauthBusy] = useState('');
  const [error, setError] = useState('');
  const submit = async (e) => { e.preventDefault(); setBusy(true); setError(''); try { const result = await (mode === 'login' ? api.login({ email: form.email, password: form.password }) : api.register(form)); if (!result.session?.access_token) { setError(`Confirmation email sent to ${form.email}. Your account is waiting for confirmation; open the link in that email, then sign in.`); return; } setToken(result.session.access_token); onAuth(result.user); navigate('/'); } catch (err) { setError(err.message || 'Authentication could not be completed. Please try again.'); } finally { setBusy(false); } };
  const oauth = async (provider) => { setOauthBusy(provider); setError(''); try { const result = await api.oauth(provider); if (!result?.url) throw new Error(); window.location.assign(result.url); } catch { setOauthBusy(''); setError(`Could not start ${provider === 'google' ? 'Google' : 'GitHub'} sign-in. Please try again.`); } };
  return <div className="auth-layout"><div className="auth-art"><div className="brand"><span className="brand-mark">A</span><span>ArchStudio<span className="accent">AI</span></span></div><div className="auth-quote"><h1><span className="quote-mark">“</span>Give your codebase a second brain.<span className="quote-mark">”</span></h1><p>Understand, visualize and explain your software projects with grounded local AI.</p></div><div className="auth-orbit">{['RAG', 'QWEN', 'CODE', 'FLOW'].map((x, i) => <span key={x} style={{ '--i': i }}>{x}</span>)}</div></div><div className="auth-panel"><div className="auth-form"><div className="eyebrow">{mode === 'login' ? 'WELCOME BACK' : 'GET STARTED'}</div><h2>{mode === 'login' ? 'Sign in to your workspace' : 'Create your workspace'}</h2><p className="muted">{mode === 'login' ? 'Your project intelligence is waiting.' : 'Turn any repository into a living knowledge base.'}</p><form onSubmit={submit} autoComplete="off">{mode === 'register' && <label>Full name<input required autoComplete="off" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label>}<label>Email<input required type="email" autoComplete="off" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></label><label>Password<input required type="password" autoComplete="new-password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} /></label>{mode === 'register' && <label>Confirm password<input required type="password" autoComplete="new-password" value={form.confirm_password} onChange={e => setForm({ ...form, confirm_password: e.target.value })} /></label>}<button className="primary-button wide" disabled={busy || !!oauthBusy}>{busy ? 'Signing in…' : mode === 'login' ? 'Sign in' : 'Create account'}</button></form>{mode === 'login' && <Link className="forgot-password" to="/forgot-password">Forgot password?</Link>}<div className="oauth-divider"><span>OR</span></div><div className="oauth-options"><button className="secondary-button oauth-button" disabled={busy || !!oauthBusy} onClick={() => oauth('google')}><strong>G</strong>{oauthBusy === 'google' ? 'Connecting…' : 'Continue with Google'}</button><button className="secondary-button oauth-button" disabled={busy || !!oauthBusy} onClick={() => oauth('github')}><strong>◈</strong>{oauthBusy === 'github' ? 'Connecting…' : 'Continue with GitHub'}</button></div>{error && <div className={error.startsWith('Confirmation email sent') ? 'notice-box' : 'error-box'}>{error}</div>}<p className="switch-auth">{mode === 'login' ? 'New to ArchStudioAI?' : 'Already have an account?'} <Link to={mode === 'login' ? '/register' : '/login'}>{mode === 'login' ? 'Create an account' : 'Sign in'}</Link></p></div></div></div>;
}

function AuthPage({ mode, onAuth }) {
  const navigate = useNavigate();
  const [form, setForm] = useState({ name: '', email: '', password: '', confirm_password: '' });
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const submit = async (e) => { e.preventDefault(); setBusy(true); setError(''); try { const result = await (mode === 'login' ? api.login({ email: form.email, password: form.password }) : api.register(form)); if (!result.session?.access_token) { setError('Check your email to confirm your account, then sign in.'); return; } setToken(result.session.access_token); onAuth(result.user); navigate('/'); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  return <div className="auth-layout"><div className="auth-art"><div className="brand"><span className="brand-mark">A</span><span>ArchStudio<span className="accent">AI</span></span></div><div className="auth-quote"><h1><span className="quote-mark">“</span>Give your codebase a second brain.<span className="quote-mark">”</span></h1><p>Understand, visualize and explain your software projects with grounded local AI.</p></div><div className="auth-orbit">{['RAG', 'QWEN', 'CODE', 'FLOW'].map((x, i) => <span key={x} style={{ '--i': i }}>{x}</span>)}</div></div><div className="auth-panel"><div className="auth-form"><div className="eyebrow">{mode === 'login' ? 'WELCOME BACK' : 'GET STARTED'}</div><h2>{mode === 'login' ? 'Sign in to your workspace' : 'Create your workspace'}</h2><p className="muted">{mode === 'login' ? 'Your project intelligence is waiting.' : 'Turn any repository into a living knowledge base.'}</p><form onSubmit={submit} autoComplete="off">{mode === 'register' && <label>Full name<input required autoComplete="off" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label>}<label>Email<input required type="email" autoComplete="off" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></label><label>Password<input required type="password" autoComplete="new-password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} /></label>{mode === 'register' && <label>Confirm password<input required type="password" autoComplete="new-password" value={form.confirm_password} onChange={e => setForm({ ...form, confirm_password: e.target.value })} /></label>}{error && <div className="error-box">{error}</div>}<button className="primary-button wide" disabled={busy}>{busy ? <Spinner /> : mode === 'login' ? 'Enter workspace →' : 'Create account →'}</button></form><p className="switch-auth">{mode === 'login' ? 'New to ArchStudioAI?' : 'Already have an account?'} <Link to={mode === 'login' ? '/register' : '/login'}>{mode === 'login' ? 'Create an account' : 'Sign in'}</Link></p></div></div></div>;
}

function Dashboard() { const [projects, setProjects] = useState(() => [...projectListCache]); const [loading, setLoading] = useState(() => projectListCache.length === 0); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [showAll, setShowAll] = useState(false); const load = () => api.projects().then(result => { cacheProjects(result); setProjects(result); }).catch(() => {}).finally(() => setLoading(false)); useEffect(() => { load(); }, []); const upload = async e => { const file = e.target.files?.[0]; if (!file) return; setBusy(true); setError(''); try { const p = await api.upload(file, file.name.replace(/\.zip$/i, '')); cacheProject(p); await api.process(p.id); load(); } catch (err) { setError(err.message); } finally { setBusy(false); e.target.value = ''; } }; const ready = projects.filter(p => p.status === 'embedded').length; return <><PageHeader eyebrow="OVERVIEW" title="Good to see you." subtitle="Connect a codebase, then open its dedicated AI workspace." action={<label className="primary-button upload-button">＋ Upload ZIP<input type="file" accept=".zip,application/zip" onChange={upload} /></label>} /><div className="stats-grid"><Stat label="Total projects" value={loading ? '—' : projects.length} note="Your connected codebases" icon="◈" /><Stat label="Ready for AI" value={loading ? '—' : ready} note="Indexed with project RAG" icon="✦" accent /><Stat label="In progress" value={loading ? '—' : projects.filter(p => ['processing', 'embedding'].includes(p.status)).length} note="Background jobs running" icon="◌" /></div>{error && <div className="error-box">{error}</div>}{busy && <div className="notice"><Spinner /> Processing your upload…</div>}<GitHubCreate onCreated={load} onError={setError} /><section className="section-heading"><div><div className="eyebrow">YOUR WORKSPACE</div><h3>Recent projects</h3></div></section>{loading ? <LoadingCard /> : projects.length ? <><div className="project-grid">{projects.slice(0, showAll ? projects.length : 6).map(p => <ProjectCard key={p.id} project={p} />)}</div>{projects.length > 6 && <button className="secondary-button more-projects-button" onClick={() => setShowAll(value => !value)}>{showAll ? 'Show fewer projects' : `More projects (${projects.length - 6})`}</button>}</> : <EmptyState icon="◈" title="Your workspace is empty" text="Upload a repository to let ArchStudioAI map its architecture and behavior." action={<label className="primary-button upload-button">Upload your first project<input type="file" accept=".zip" onChange={upload} /></label>} />}</>; }
function Stat({ label, value, note, icon, accent }) { return <div className="stat-card"><div className={`stat-icon ${accent ? 'accent-bg' : ''}`}>{icon}</div><div><span className="muted">{label}</span><strong>{value}</strong><small>{note}</small></div></div>; }
function PageHeader({ eyebrow, title, subtitle, action }) { return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p className="muted">{subtitle}</p></div>{action}</div>; }
function Projects() { const [projects, setProjects] = useState([]); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const load = () => api.projects().then(setProjects).catch(e => setError(e.message)); useEffect(() => { load(); const timer = setInterval(load, 3000); return () => clearInterval(timer); }, []); const upload = async (e) => { const file = e.target.files?.[0]; if (!file) return; setBusy(true); setError(''); try { const p = await api.upload(file, file.name.replace(/\.zip$/i, '')); await api.process(p.id); load(); } catch (err) { setError(err.message); } finally { setBusy(false); e.target.value = ''; } }; return <><PageHeader eyebrow="PROJECTS" title="Your projects" subtitle="Connect a codebase and build its private AI knowledge base." action={<label className="primary-button upload-button">＋ Upload ZIP<input type="file" accept=".zip,application/zip" onChange={upload} /></label>} />{error && <div className="error-box">{error}</div>}{busy && <div className="notice"><Spinner /> Processing your upload…</div>}<GitHubCreate onCreated={load} onError={setError} /><div className="project-grid">{projects.map(p => <ProjectCard key={p.id} project={p} />)}</div>{!projects.length && !busy && <EmptyState icon="⌂" title="No projects yet" text="Start with a ZIP archive of your project. We’ll process it safely in the background." action={<label className="primary-button upload-button">Upload project<input type="file" accept=".zip" onChange={upload} /></label>} />}</>; }
function GitHubCreate({ onCreated, onError }) { const [url, setUrl] = useState(''); const [name, setName] = useState(''); const [busy, setBusy] = useState(false); const submit = async e => { e.preventDefault(); setBusy(true); try { const project = await api.github(url, name); await api.retrieve(project.id); setUrl(''); setName(''); onCreated(); } catch (err) { onError(err.message); } finally { setBusy(false); } }; return <form className="github-create" onSubmit={submit}><div><div className="eyebrow">OR CONNECT GITHUB</div><strong>Start from a public repository</strong><p className="muted">The backend validates the repository before retrieval.</p></div><input required type="url" placeholder="https://github.com/org/repository" value={url} onChange={e => setUrl(e.target.value)} /><input placeholder="Project name (optional)" value={name} onChange={e => setName(e.target.value)} /><button className="secondary-button" disabled={busy}>{busy ? 'Connecting…' : 'Connect repository'}</button></form>; }
function ProjectCard({ project }) { const [deleting, setDeleting] = useState(false); const remove = async e => { e.preventDefault(); e.stopPropagation(); if (!window.confirm(`Delete project “${project.name}”? This cannot be undone.`)) return; setDeleting(true); try { await api.deleteProject(project.id); window.location.reload(); } catch (err) { window.alert(err.message); setDeleting(false); } }; return <Link className="project-card" to={`/projects/${project.id}`}><div className="card-top"><div className="project-symbol">{project.name[0]?.toUpperCase()}</div><div className="card-actions"><Status status={project.status} /><button type="button" className="project-more" aria-label={`Delete ${project.name}`} title="Delete project" onClick={remove}>{deleting ? 'Deleting…' : 'Delete'}</button></div></div><h3>{project.name}</h3><p className="muted ellipsis">{project.original_filename || project.source_url || 'Uploaded project'}</p><div className="card-footer"><span>{new Date(project.updated_at).toLocaleDateString()}</span><span>Open workspace →</span></div></Link>; }
function Status({ status }) { const busy = status === 'processing' || status === 'embedding'; return <span className={`status status-${status}`}><span />{busy && <Spinner />}{statuses[status] || status}</span>; }
function Workspace() { const { id } = useParams(); const { project, error } = useProject(id); if (error) return <ErrorState text={error} />; if (!project) return <LoadingCard />; return <><div className="workspace-breadcrumb"><Link className="back-link" to="/">← Dashboard</Link><span>Workspace /</span><strong>{project.name}</strong></div><PageHeader eyebrow="PROJECT WORKSPACE" title={project.name} subtitle={project.status_message || 'Your codebase intelligence workspace.'} action={<Status status={project.status} />} /><div className="workspace-grid"><div className="workspace-main"><div className="workspace-tabs"><Link className="tab active" to={`/projects/${id}`}>Overview</Link><Link className="tab" to={`/projects/${id}/reports`}>Reports</Link><Link className="tab" to={`/projects/${id}/diagrams`}>Diagrams</Link><Link className="tab" to={`/projects/${id}/research`}>Research</Link><Link className="tab" to={`/projects/${id}/chat`}>Chat</Link></div><WorkspaceActions project={project} /><div className="workspace-panels"><InfoPanel title="Project status"><Status status={project.status} /><p className="muted">{project.status_message || 'No status message.'}</p></InfoPanel><InfoPanel title="Source"><p>{project.source_type === 'github' ? project.source_url : project.original_filename || 'ZIP upload'}</p><small className="muted">Created {new Date(project.created_at).toLocaleString()}</small></InfoPanel><InfoPanel title="What’s next"><p className="muted">{project.status === 'embedded' ? 'Your project is ready for reports, diagrams and chat.' : 'Processing steps will appear here as they complete.'}</p></InfoPanel></div></div><aside className="workspace-aside"><div className="aside-label">PROJECT SIGNAL</div><div className="signal"><div className="signal-ring">{project.status === 'embedded' ? '✓' : '…'}</div><strong>{project.status === 'embedded' ? 'AI ready' : 'Building index'}</strong><p className="muted">{project.status === 'embedded' ? 'Semantic retrieval is active.' : 'This page updates when the background job finishes.'}</p></div></aside></div></>; }
function parseEstimate(message) { const match = message?.match(/about\s+(\d+)\s+(seconds?|minutes?|mins?)/i); if (!match) return null; const value = Number(match[1]); return { seconds: /minute|min/i.test(match[2]) ? value * 60 : value, label: `${value} ${match[2]}` }; }
function LiveReadyEstimate({ project }) { const parsed = parseEstimate(project.status_message); const estimate = parsed; const estimateKey = `${project.status}:${estimate?.seconds || 0}:${project.updated_at || ""}`; const target = React.useRef(null); const lastKey = React.useRef(''); const [remaining, setRemaining] = useState(estimate?.seconds || 0); useEffect(() => { if (project.status !== 'embedding' || !estimate) return; if (lastKey.current !== estimateKey) { lastKey.current = estimateKey; const anchor = new Date(project.updated_at || Date.now()).getTime(); target.current = anchor + estimate.seconds * 1000; setRemaining(estimate.seconds); } }, [estimateKey, project.status, estimate]); useEffect(() => { if (project.status !== 'embedding' || !target.current) return; const tick = () => setRemaining(Math.max(0, Math.ceil((target.current - Date.now()) / 1000))); tick(); const timer = setInterval(tick, 1000); return () => clearInterval(timer); }, [project.status, estimateKey, project.updated_at]); if (project.status !== 'embedding') return null; if (!estimate) return <div className="ready-estimate"><Spinner /> AI is processing your codebase. Please wait; a time estimate is not available yet.</div>; if (remaining <= 0) return <div className="ready-estimate"><Spinner /> AI is still processing your codebase. Waiting for the next backend progress update.</div>; const minutes = Math.floor(remaining / 60); const seconds = remaining % 60; return <div className="ready-estimate"><Spinner /> AI is processing your codebase. Estimated time remaining: <strong>{minutes > 0 ? `${minutes} min ` : ''}{String(seconds).padStart(2, '0')} sec</strong></div>; }
function WorkspaceActions({ project }) { const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const act = async (fn, label) => { setBusy(true); setMessage(''); try { const r = await fn(project.id); setMessage(r.message || `${label} started.`); } catch (e) { setMessage(e.message); } finally { setBusy(false); } }; return <div className="action-strip"><div><div className="eyebrow">QUICK ACTIONS</div><h3>Anything can be done for this project</h3><p className="muted">Generate, inspect and refine grounded project artifacts.</p><LiveReadyEstimate project={project} /></div><div className="action-buttons">{project.status === 'processed' && <button className="primary-button" disabled={busy} onClick={() => act(api.embed, 'Embedding')}>{busy ? <><Spinner /> Building AI index…</> : '✦ Build AI index'}</button>}{project.status === 'ready' && <button className="primary-button" disabled={busy} onClick={() => act(api.process, 'Processing')}>{busy ? <><Spinner /> Processing codebase…</> : 'Process codebase'}</button>}{project.status === 'embedded' && <><Link className="secondary-button" to={`/projects/${project.id}/reports`}>▤ Generate report</Link><Link className="secondary-button" to={`/projects/${project.id}/diagrams`}>⌁ Architecture diagrams</Link><Link className="secondary-button" to={`/projects/${project.id}/chat`}>✦ Ask AI</Link></>}</div>{message && <div className="action-message">{message}</div>}</div>; }
function InfoPanel({ title, children }) { return <div className="info-panel"><div className="eyebrow">{title}</div>{children}</div>; }

function ArtifactLibrary({ kind }) { const { id } = useParams(); const { project } = useProject(id); const [projects, setProjects] = useState([]); useEffect(() => { if (id) { if (project) setProjects([project]); return; } api.projects().then(result => { cacheProjects(result); setProjects(result); }).catch(() => {}); }, [id, project]); const projectPath = id ? `/projects/${id}` : '/'; const backLabel = id ? '← Back to workspace' : '← Back to dashboard'; return <><div className="feature-back"><Link className="back-link" to={projectPath}>{backLabel}</Link></div><PageHeader eyebrow={kind === 'diagrams' ? 'VISUAL INTELLIGENCE' : kind === 'research' ? 'RESEARCH' : 'DOCUMENTS'} title={kind === 'diagrams' ? 'Diagrams' : kind === 'research' ? 'Research papers' : 'Reports'} subtitle={id ? 'Generate and refine grounded output for this project.' : 'Choose a project to generate and refine grounded output.'} />{projects.length ? <div className={`library-grid ${id ? 'scoped-library' : ''}`}>{projects.map(p => <LibraryProject key={p.id} project={p} kind={kind} scoped={Boolean(id)} />)}</div> : <EmptyState icon="▤" title="Project unavailable" text="Return to the dashboard and open a project to generate grounded artifacts." action={<Link to="/" className="primary-button">Back to dashboard</Link>} />}</>; }
function ArtifactViewer({ project, artifact, onUpdate }) { const doc = artifact.document; const diagram = artifact.diagram; const [editing, setEditing] = useState(false); const [draft, setDraft] = useState(doc || diagram); const [saving, setSaving] = useState(false); const [downloadError, setDownloadError] = useState(''); useEffect(() => setDraft(doc || diagram), [artifact.artifact_id, artifact.updated_at]); const save = async () => { setSaving(true); try { const result = await api.updateArtifact(project.id, artifact.artifact_id, doc ? { document: draft } : { diagram: draft }); onUpdate(result); setEditing(false); } catch (e) { alert(e.message); } finally { setSaving(false); } }; const download = async (format) => { setDownloadError(''); try { const response = await fetch(api.downloadUrl(project.id, artifact.artifact_id, format), { headers: { Authorization: `Bearer ${localStorage.getItem('archstudio_token')}` } }); if (!response.ok) { const body = await response.json().catch(() => null); throw new Error(body?.detail || `Download failed (${response.status}).`); } const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `${artifact.kind}.${format}`; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); } catch (e) { setDownloadError(e.message || 'Download could not be completed.'); } }; const formats = doc ? ['pdf','docx'] : ['svg','png','pdf']; const updateAuthor = (i, key, value) => { const authors = [...draft.authors]; authors[i] = { ...authors[i], [key]: value }; setDraft({ ...draft, authors }); }; return <div className="artifact-viewer"><div className="viewer-head"><strong>{doc ? doc.title : diagram.title}</strong><div className="viewer-actions"><button className="text-button" onClick={() => setEditing(!editing)}>{editing ? 'Cancel' : 'Edit'}</button>{editing && <button className="small-primary" disabled={saving} onClick={save}>{saving ? 'Saving…' : 'Save'}</button>}{formats.map(f => <button className="download" key={f} onClick={() => download(f)}>↓ {f.toUpperCase()}</button>)}</div></div>{downloadError && <div className="error-box compact">{downloadError}</div>}{doc ? <div className="document-preview">{editing ? <><label className="document-field-label">Paper title<input value={draft.title} placeholder="Enter paper title" onChange={e => setDraft({ ...draft, title: e.target.value })} /></label>{(draft.authors || []).map((a, i) => <div key={i} className="author-fields"><label className="document-field-label">Author name<input value={a.name} placeholder="Enter author name" onChange={e => updateAuthor(i, 'name', e.target.value)} /></label><label className="document-field-label">Institution / affiliation (optional)<input value={a.institution} placeholder="Enter institution or affiliation" onChange={e => updateAuthor(i, 'institution', e.target.value)} /></label></div>)}{draft.sections.map((s, i) => <div key={i}><label className="document-field-label">{s.heading}{['Literature Review', 'Research Gap & Motivation', 'Comparison with Existing System', 'References'].includes(s.heading) && <span className="user-input-tag">GROQ DRAFT · EDITABLE</span>}<textarea value={s.content} onChange={e => { const sections = [...draft.sections]; sections[i] = { ...s, content: e.target.value }; setDraft({ ...draft, sections }); }} /></label></div>)}</> : <>{doc.authors?.map((a, i) => <span key={i}>{a.name}{a.institution ? ` · ${a.institution}` : ''}{i < doc.authors.length - 1 ? ' | ' : ''}</span>)}{doc.sections.map(s => <div key={s.heading}><h4>{s.heading}</h4><p>{s.content}</p></div>)}</>}</div> : <div className="diagram-preview"><Mermaid source={diagram.mermaid} /><details><summary>Mermaid source</summary><textarea value={editing ? draft.mermaid : diagram.mermaid} readOnly={!editing} onChange={e => setDraft({ ...draft, mermaid: e.target.value })} /></details></div>}</div>; }
function Mermaid({ source }) { const [svg, setSvg] = useState(''); const schema = source.trim().startsWith('erDiagram'); const embedded = source.match(/^%% ARCHSTUDIO_EXPLANATION (.*)$/m)?.[1]; const labels = [...source.matchAll(/\["([^\"]+)"\]/g)].map(match => match[1]); const walkthrough = embedded || (schema ? `Each box is a database table. The fields inside each table are the columns stored for that record type. Data is written to these tables by the backend and read back when the application needs to load, update, or display project information. The schema diagram shows storage structure; it does not claim a relationship unless one is explicitly drawn. Tables detected: ${labels.join(', ') || 'the tables shown above'}.` : `Each box is a source component, library, runtime, or output identified from the repository. Data or control moves along the arrows: a dependency arrow means the upstream component relies on the downstream component, while an output arrow indicates where the processed result is rendered or returned. The flow begins at the entry/UI components, passes through the dependent implementation and runtime pieces, and ends at the application output represented above. Components detected: ${labels.join(', ') || 'the components shown above'}.`); useEffect(() => { let live = true; mermaid.initialize({ startOnLoad: false, theme: document.documentElement.dataset.theme === 'batman' ? 'dark' : 'neutral', securityLevel: 'strict' }); mermaid.render(`diagram-${Math.random().toString(36).slice(2)}`, source).then(({ svg }) => live && setSvg(svg)).catch(() => live && setSvg('')); return () => { live = false; }; }, [source]); return svg ? <><div className="mermaid" dangerouslySetInnerHTML={{ __html: svg }} /><div className="diagram-explanation"><div className="eyebrow">DIAGRAM EXPLANATION</div><p>{walkthrough}</p></div></> : <div className="diagram-empty">Diagram source is available below.</div>; }

function GlobalChat() { const { id } = useParams(); const { project } = useProject(id); const [projects, setProjects] = useState([]); useEffect(() => { if (id) { if (project) setProjects([project]); return; } api.projects().then(result => { cacheProjects(result); setProjects(result); }).catch(() => {}); }, [id, project]); const backPath = id ? `/projects/${id}` : '/'; const backLabel = id ? '← Back to workspace' : '← Back to dashboard'; return <><div className="feature-back"><Link className="back-link" to={backPath}>{backLabel}</Link></div>{projects.length ? <Chat project={projects.find(p => p.status === 'embedded') || projects[0]} /> : <EmptyState icon="◌" title="Chat needs a project" text="Embed a project to ask grounded questions about its code." action={<Link className="primary-button" to="/">Back to dashboard</Link>} />}</>; }
function Chat({ project }) { const [messages, setMessages] = useState([]); const [query, setQuery] = useState(''); const [busy, setBusy] = useState(false); const send = async (e) => { e.preventDefault(); if (!query.trim() || busy) return; const q = query.trim(); setQuery(''); setMessages(m => [...m, { role: 'user', text: q }]); setBusy(true); try { const r = await api.chat(project.id, q); setMessages(m => [...m, { role: 'ai', text: r.answer, evidence: r.evidence }]); } catch (err) { setMessages(m => [...m, { role: 'error', text: err.message }]); } finally { setBusy(false); } }; return <div className="chat-page"><PageHeader eyebrow="PROJECT CHAT" title="Ask anything about your code." subtitle={`Answers are grounded in ${project.name}'s indexed repository.`} action={<Status status={project.status} />} /><div className="chat-window">{!messages.length && <div className="chat-welcome"><div className="ai-orb">✦</div><h2>Your codebase, explained.</h2><p className="muted">Ask about architecture, behavior, libraries or where something is implemented.</p><div className="suggestions">{['Where is authentication implemented?', 'Which libraries are used?', 'Explain the main data flow.'].map(x => <button key={x} onClick={() => setQuery(x)}>{x} <span>↗</span></button>)}</div></div>}{messages.map((m, i) => <div className={`message ${m.role}`} key={i}><div className="message-avatar">{m.role === 'user' ? 'You' : '✦'}</div><div><p>{m.text}</p>{m.evidence?.length > 0 && <div className="evidence">{m.evidence.map((e, j) => <span key={j}>⌘ {e.file_path}:{e.start_line || '?'}–{e.end_line || '?'}</span>)}</div>}</div></div>)}{busy && <div className="message ai"><div className="message-avatar">✦</div><div className="typing"><span /><span /><span /></div></div>}<form className="chat-input" onSubmit={send}><input value={query} onChange={e => setQuery(e.target.value)} placeholder={`Ask about ${project.name}…`} /><button className="primary-button">Send ↑</button></form></div></div>; }
function LoadingCard() { return <div className="loading-card"><Spinner /> Loading workspace data…</div>; }
function Spinner() { return <span className="spinner" />; }
function EmptyState({ icon, title, text, action }) { return <div className="empty-state"><div className="empty-icon">{icon}</div><h2>{title}</h2><p className="muted">{text}</p>{action}</div>; }
function ErrorState({ text }) { return <div className="error-page"><div className="empty-icon">!</div><h2>Something went wrong</h2><p className="muted">{text}</p><Link className="secondary-button" to="/">Return to dashboard</Link></div>; }

export { LiteratureReview };
export default App;
// Predefined report formats are selected by the user; report templates are not uploaded.
function LibraryProject({ project, kind, scoped }) {
  const artifactStorageKey = `archstudio_paper_${project.id}`; const [artifact, setArtifact] = useState(() => { try { return JSON.parse(sessionStorage.getItem(artifactStorageKey) || 'null'); } catch { return null; } }); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  useEffect(() => { api.artifacts(project.id).then(items => { const paper = items.find(item => ['report', 'ieee_report'].includes(item.kind) && item.status === 'completed'); if (paper) setArtifact(paper); }).catch(() => {}); }, [project.id]);
  const options = kind === 'research'
    ? [['report', 'Report'], ['ieee_report', 'IEEE Report']]
    : kind === 'diagrams'
      ? [['architecture_diagram', 'Architecture / data flow'], ['database_diagram', 'Database schema']]
      : [['report', 'Report'], ['ieee_report', 'IEEE Report']];
  const generate = async type => { setBusy(true); setError(''); try { const start = await api.queueArtifact(project.id, type); setArtifact({ ...start }); const timer = setInterval(async () => { try { const result = await api.artifact(project.id, start.artifact_id); setArtifact(result); if (['completed', 'failed'].includes(result.status)) { clearInterval(timer); setBusy(false); if (result.status === 'failed') setError(result.error || 'Artifact generation failed.'); } } catch (err) { clearInterval(timer); setBusy(false); setError(err.message); } }, 1800); } catch (err) { setError(err.message); setBusy(false); } };
  return <div className={`library-card ${scoped ? 'scoped-project' : ''}`}><div className="card-top"><div className="project-symbol">{project.name[0]}</div><Status status={project.status} /></div><h3>{project.name}</h3><p className="muted">{project.status === 'embedded' ? 'Choose a predefined format for grounded generation.' : 'Complete processing and indexing first.'}</p>{kind === 'reports' && <div className="notice-box">For richer Literature Review, Research Gap, comparison, and references, open the separate <strong>Research</strong> section first. You can copy that content into the matching editable report sections after generation.</div>}{error && <div className="error-box compact">{error}</div>}<div className="artifact-options">{options.map(([type, label]) => { const current = artifact?.kind === type ? artifact : null; const active = busy && current; return <button key={type} className="artifact-option" disabled={busy || project.status !== 'embedded'} aria-busy={Boolean(active)} onClick={() => generate(type)}><span>{active ? <Spinner /> : type.includes('diagram') ? '⌁' : '▤'}</span><div><strong>{label}</strong><small>{active ? (current.status === 'queued' ? 'Queued…' : 'Generating…') : current?.status || 'Generate'}</small></div><b>→</b></button>; })}</div>{artifact?.status === 'completed' && <ArtifactViewer project={project} artifact={artifact} onUpdate={setArtifact} />}</div>;
}
